import { select as d3_select } from 'd3-selection';
import { geoScaleToZoom } from '@id-sdk/math';
import _throttle from 'lodash-es/throttle';
import { services } from '../services';
import { svgPath, svgPointTransform } from './index';
var _enabled = false;
var _initialized = false;

var _FbMlService;

var _EsriService;

var _actioned;

export function svgRapidFeatures(projection, context, dispatch) {
  var RAPID_MAGENTA = '#da26d3';

  var throttledRedraw = _throttle(function () {
    return dispatch.call('change');
  }, 1000);

  var gpxInUrl = context.initialHashParams.hasOwnProperty('gpx');

  var _layer = d3_select(null);

  function init() {
    if (_initialized) return; // run once

    _enabled = true;
    _initialized = true;
    _actioned = new Set(); // Watch history to synchronize the displayed layer with features
    // that have been accepted or rejected by the user.

    context.history().on('undone.aifeatures', onHistoryUndone);
    context.history().on('change.aifeatures', onHistoryChange);
    context.history().on('restore.aifeatures', onHistoryRestore);
  } // Services are loosly coupled in iD, so we use these functions
  // to gain access to them, and bind the event handlers a single time.


  function getFbMlService() {
    if (services.fbMLRoads && !_FbMlService) {
      _FbMlService = services.fbMLRoads;

      _FbMlService.event.on('loadedData', throttledRedraw);
    }

    return _FbMlService;
  }

  function getEsriService() {
    if (services.esriData && !_EsriService) {
      _EsriService = services.esriData;

      _EsriService.event.on('loadedData', throttledRedraw);
    }

    return _EsriService;
  }

  function wasRapidEdit(annotation) {
    return annotation && annotation.type && /^rapid/.test(annotation.type);
  }

  function onHistoryUndone(currentStack, previousStack) {
    var annotation = previousStack.annotation;
    if (!wasRapidEdit(annotation)) return;

    _actioned.delete(annotation.id);

    if (_enabled) {
      dispatch.call('change');
    } // redraw

  }

  function
    /* difference */
  onHistoryChange() {
    var annotation = context.history().peekAnnotation();
    if (!wasRapidEdit(annotation)) return;

    _actioned.add(annotation.id);

    if (_enabled) {
      dispatch.call('change');
    } // redraw

  }

  function onHistoryRestore() {
    _actioned = new Set();
    context.history().peekAllAnnotations().forEach(function (annotation) {
      if (wasRapidEdit(annotation)) {
        _actioned.add(annotation.id); // origid (the original entity ID), a.k.a. datum.__origid__,
        // is a hack used to deal with non-deterministic way-splitting
        // in the roads service. Each way "split" will have an origid
        // attribute for the original way it was derived from. In this
        // particular case, restoring from history on page reload, we
        // prevent new splits (possibly different from before the page
        // reload) from being displayed by storing the origid and
        // checking against it in render().


        if (annotation.origid) {
          _actioned.add(annotation.origid);
        }
      }
    });

    if (_actioned.size && _enabled) {
      dispatch.call('change'); // redraw
    }
  }

  function showLayer() {
    throttledRedraw();
    layerOn();
  }

  function hideLayer() {
    throttledRedraw.cancel();
    layerOff();
  }

  function layerOn() {
    _layer.style('display', 'block');
  }

  function layerOff() {
    _layer.style('display', 'none');
  }

  function isArea(d) {
    return d.type === 'relation' || d.type === 'way' && d.isArea();
  }

  function featureKey(d) {
    return d.__fbid__;
  }

  function render(selection) {
    var rapidContext = context.rapidContext(); // Ensure Rapid layer and <defs> exists

    _layer = selection.selectAll('.layer-ai-features').data(_enabled ? [0] : []);

    _layer.exit().remove();

    var layerEnter = _layer.enter().append('g').attr('class', 'layer-ai-features');

    layerEnter.append('defs').attr('class', 'rapid-defs');
    _layer = layerEnter.merge(_layer);
    var surface = context.surface();
    var waitingForTaskExtent = gpxInUrl && !rapidContext.getTaskExtent();
    if (!surface || surface.empty() || waitingForTaskExtent) return; // not ready to draw yet, starting up
    // Gather available datasets, generate a unique fill pattern
    // and a layer group for each dataset. Fill pattern styling is complicated.
    // Style needs to apply in the def, not where the pattern is used.

    var rapidDatasets = rapidContext.datasets();
    var datasets = Object.values(rapidDatasets).filter(function (dataset) {
      return dataset.added && dataset.enabled;
    });

    var defs = _layer.selectAll('.rapid-defs');

    var dsPatterns = defs.selectAll('.rapid-fill-pattern').data(datasets, function (d) {
      return d.id;
    }); // exit

    dsPatterns.exit().remove(); // enter

    var dsPatternsEnter = dsPatterns.enter().append('pattern').attr('id', function (d) {
      return "fill-".concat(window.toBase64(d.id));
    }).attr('class', 'rapid-fill-pattern').attr('width', 5).attr('height', 15).attr('patternUnits', 'userSpaceOnUse').attr('patternTransform', function (d, i) {
      var r = (45 + 67 * i) % 180; // generate something different for each layer

      return "rotate(".concat(r, ")");
    });
    dsPatternsEnter.append('line').attr('class', 'ai-building-line').attr('stroke', 'currentColor').attr('stroke-width', '2px').attr('stroke-opacity', 0.6).attr('y2', '15'); // update

    dsPatterns = dsPatternsEnter.merge(dsPatterns).style('color', function (d) {
      return d.color || RAPID_MAGENTA;
    });

    var dsGroups = _layer.selectAll('.layer-rapid-dataset').data(datasets, function (d) {
      return d.id;
    }); // exit


    dsGroups.exit().remove(); // enter/update

    dsGroups = dsGroups.enter().append('g').attr('class', function (d) {
      return "layer-rapid-dataset layer-rapid-dataset-".concat(d.id);
    }).merge(dsGroups).style('color', function (d) {
      return d.color || RAPID_MAGENTA;
    }).each(eachDataset);
  }

  function eachDataset(dataset, i, nodes) {
    var rapidContext = context.rapidContext();
    var selection = d3_select(nodes[i]);
    var service = dataset.service === 'fbml' ? getFbMlService() : getEsriService();
    if (!service) return; // Adjust the dataset id for whether we want the data conflated or not.

    var internalID = dataset.id + (dataset.conflated ? '-conflated' : '');
    var graph = service.graph(internalID);
    var getPath = svgPath(projection, graph);
    var getTransform = svgPointTransform(projection); // Gather data

    var geoData = {
      paths: [],
      vertices: [],
      points: []
    };

    if (context.map().zoom() >= context.minEditableZoom()) {
      /* Facebook AI/ML */
      if (dataset.service === 'fbml') {
        service.loadTiles(internalID, projection, rapidContext.getTaskExtent(), context);
        var pathData = service.intersects(internalID, context.map().extent()).filter(function (d) {
          return d.type === 'way' && !_actioned.has(d.id) && !_actioned.has(d.__origid__);
        }) // see onHistoryRestore()
        .filter(getPath); // fb_ai service gives us roads and buildings together,
        // so filter further according to which dataset we're drawing

        if (dataset.id === 'fbRoads' || dataset.id === 'rapid_intro_graph') {
          geoData.paths = pathData.filter(function (d) {
            return !!d.tags.highway;
          });
          var seen = {};
          geoData.paths.forEach(function (d) {
            var first = d.first();
            var last = d.last();

            if (!seen[first]) {
              seen[first] = true;
              geoData.vertices.push(graph.entity(first));
            }

            if (!seen[last]) {
              seen[last] = true;
              geoData.vertices.push(graph.entity(last));
            }
          });
        } else if (dataset.id === 'msBuildings') {
          geoData.paths = pathData.filter(isArea); // no vertices
        } else {
          // esri data via fb service
          geoData.paths = pathData.filter(isArea);
        }
        /* ESRI ArcGIS */

      } else if (dataset.service === 'esri') {
        service.loadTiles(internalID, projection, null, context);
        var visibleData = service.intersects(internalID, context.map().extent()).filter(function (d) {
          return !_actioned.has(d.id) && !_actioned.has(d.__origid__);
        }); // see onHistoryRestore()

        geoData.points = visibleData.filter(function (d) {
          return d.type === 'node' && !!d.__fbid__;
        }); // standalone only (not vertices/childnodes)

        geoData.paths = visibleData.filter(function (d) {
          return d.type === 'way' || d.type === 'relation';
        }).filter(getPath);
      }
    }

    selection.call(drawPaths, geoData.paths, dataset, getPath).call(drawVertices, geoData.vertices, getTransform).call(drawPoints, geoData.points, getTransform);
  }

  function drawPaths(selection, pathData, dataset, getPath) {
    // Draw shadow, casing, stroke layers
    var linegroups = selection.selectAll('g.linegroup').data(['shadow', 'casing', 'stroke']);
    linegroups = linegroups.enter().append('g').attr('class', function (d) {
      return "linegroup linegroup-".concat(d);
    }).merge(linegroups); // Draw paths

    var paths = linegroups.selectAll('path').data(pathData, featureKey); // exit

    paths.exit().remove(); // enter/update

    paths = paths.enter().append('path').attr('style', function (d) {
      return isArea(d) ? "fill: url(#fill-".concat(window.toBase64(dataset.id), ")") : null;
    }).attr('class', function (d, i, nodes) {
      var currNode = nodes[i];
      var linegroup = currNode.parentNode.__data__;
      var klass = isArea(d) ? 'building' : 'road';
      return "line ".concat(linegroup, " ").concat(klass, " data").concat(d.__fbid__);
    }).merge(paths).attr('d', getPath);
  }

  function drawVertices(selection, vertexData, getTransform) {
    var vertRadii = {
      //       z16-, z17,  z18+
      stroke: [3.5, 4, 4.5],
      fill: [2, 2, 2.5]
    };
    var vertexGroup = selection.selectAll('g.vertexgroup').data(vertexData.length ? [0] : []);
    vertexGroup.exit().remove();
    vertexGroup = vertexGroup.enter().append('g').attr('class', 'vertexgroup').merge(vertexGroup);
    var vertices = vertexGroup.selectAll('g.vertex').data(vertexData, function (d) {
      return d.id;
    }); // exit

    vertices.exit().remove(); // enter

    var enter = vertices.enter().append('g').attr('class', function (d) {
      return "node vertex ".concat(d.id);
    });
    enter.append('circle').attr('class', 'stroke');
    enter.append('circle').attr('class', 'fill'); // update

    var zoom = geoScaleToZoom(projection.scale());
    var radiusIdx = zoom < 17 ? 0 : zoom < 18 ? 1 : 2;
    vertices = vertices.merge(enter).attr('transform', getTransform).call(function (selection) {
      ['stroke', 'fill'].forEach(function (klass) {
        selection.selectAll('.' + klass).attr('r', vertRadii[klass][radiusIdx]);
      });
    });
  }

  function drawPoints(selection, pointData, getTransform) {
    var pointRadii = {
      //       z16-, z17,  z18+
      shadow: [4.5, 7, 8],
      stroke: [4.5, 7, 8],
      fill: [2.5, 4, 5]
    };
    var pointGroup = selection.selectAll('g.pointgroup').data(pointData.length ? [0] : []);
    pointGroup.exit().remove();
    pointGroup = pointGroup.enter().append('g').attr('class', 'pointgroup').merge(pointGroup);
    var points = pointGroup.selectAll('g.point').data(pointData, featureKey); // exit

    points.exit().remove(); // enter

    var enter = points.enter().append('g').attr('class', function (d) {
      return "node point data".concat(d.__fbid__);
    });
    enter.append('circle').attr('class', 'shadow');
    enter.append('circle').attr('class', 'stroke');
    enter.append('circle').attr('class', 'fill'); // update

    var zoom = geoScaleToZoom(projection.scale());
    var radiusIdx = zoom < 17 ? 0 : zoom < 18 ? 1 : 2;
    points = points.merge(enter).attr('transform', getTransform).call(function (selection) {
      ['shadow', 'stroke', 'fill'].forEach(function (klass) {
        selection.selectAll('.' + klass).attr('r', pointRadii[klass][radiusIdx]);
      });
    });
  }

  render.showAll = function () {
    return _enabled;
  };

  render.enabled = function (val) {
    if (!arguments.length) return _enabled;
    _enabled = val;

    if (_enabled) {
      showLayer();
    } else {
      hideLayer();
    }

    dispatch.call('change');
    return render;
  };

  init();
  return render;
}