import { select as d3_select } from 'd3-selection';
import { t } from '../core/localizer';
import { prefs } from '../core/preferences';
import { modeBrowse } from '../modes';
import { uiModal } from './modal';
export function uiRapidPowerUserFeaturesDialog(context) {
  var featureFlags = ['previewDatasets', 'tagnosticRoadCombine', 'tagSources', 'showAutoFix', 'allowLargeEdits'];
  var rapidContext = context.rapidContext();
  var showPowerUser = rapidContext.showPowerUser;

  var _modalSelection = d3_select(null);

  var _content = d3_select(null); // if we are not currently showing poweruser features, move all the feature flags to a different keyspace


  if (!showPowerUser) {
    featureFlags.forEach(function (featureFlag) {
      var val = prefs("rapid-internal-feature.".concat(featureFlag));

      if (val) {
        prefs("rapid-internal-feature.was.".concat(featureFlag), val);
        prefs("rapid-internal-feature.".concat(featureFlag), null);
      }
    });
  } else {
    featureFlags.forEach(function (featureFlag) {
      var val = prefs("rapid-internal-feature.was.".concat(featureFlag));

      if (val) {
        prefs("rapid-internal-feature.".concat(featureFlag), val);
        prefs("rapid-internal-feature.was.".concat(featureFlag), null);
      }
    });
  }

  function isEnabled(featureFlag) {
    return prefs("rapid-internal-feature.".concat(featureFlag)) === 'true';
  }

  function toggleFeature(_, featureFlag) {
    var enabled = prefs("rapid-internal-feature.".concat(featureFlag)) === 'true';
    enabled = !enabled;
    prefs("rapid-internal-feature.".concat(featureFlag), enabled); // custom on-toggle behaviors can go here

    if (featureFlag === 'previewDatasets' && !enabled) {
      // user unchecked previewDatasets feature
      var datasets = rapidContext.datasets();
      Object.values(datasets).forEach(function (ds) {
        if (ds.beta) {
          ds.added = false;
          ds.enabled = false;
        }
      });
      context.enter(modeBrowse(context)); // return to browse mode (in case something was selected)

      context.map().pan([0, 0]); // trigger a map redraw
    }
  }

  return function (selection) {
    _modalSelection = uiModal(selection);

    _modalSelection.select('.modal').attr('class', 'modal rapid-modal'); // RapiD styling


    _content = _modalSelection.select('.content').append('div').attr('class', 'rapid-stack poweruser');

    _content.call(renderModalContent);

    _content.selectAll('.ok-button').node().focus();
  };

  function renderModalContent(selection) {
    /* Header */
    var headerEnter = selection.selectAll('.modal-section-heading').data([0]).enter().append('div').attr('class', 'modal-section-heading');
    headerEnter.append('h3').attr('class', 'modal-heading').html(t('rapid_poweruser_features.heading.label'));
    headerEnter.append('div').attr('class', 'modal-heading-desc').text(t('rapid_poweruser_features.heading.description')).append('span').attr('class', 'smile').text('😎');
    /* Features */

    var features = selection.selectAll('.rapid-features-container').data([0]);
    var featuresEnter = features.enter().append('div').attr('class', 'rapid-features-container');
    features.merge(featuresEnter).call(renderFeatures);
    /* OK Button */

    var buttonsEnter = selection.selectAll('.modal-section.buttons').data([0]).enter().append('div').attr('class', 'modal-section buttons');
    buttonsEnter.append('button').attr('class', 'button ok-button action').on('click', function () {
      return _modalSelection.remove();
    }).text(t('confirm.okay'));
  }

  function renderFeatures(selection) {
    var rows = selection.selectAll('.rapid-checkbox-feature').data(featureFlags.filter(function (x) {
      return x === 'previewDatasets';
    }), function (d) {
      return d;
    }); // only show one powerUser setting: previewDatasets
    // enter

    var rowsEnter = rows.enter().append('div').attr('class', 'modal-section rapid-checkbox rapid-checkbox-feature');
    rowsEnter.append('div').attr('class', 'rapid-feature').each(function (d, i, nodes) {
      var selection = d3_select(nodes[i]); // line1: Label

      selection.append('div').attr('class', 'rapid-feature-label').text(function (d) {
        return t("rapid_poweruser_features.".concat(d, ".label"));
      }); // line2: description

      selection.append('div').attr('class', 'rapid-feature-description').text(function (d) {
        return t("rapid_poweruser_features.".concat(d, ".description"));
      });
    });
    var inputsEnter = rowsEnter.append('div').attr('class', 'rapid-checkbox-inputs');
    var checkboxEnter = inputsEnter.append('label').attr('class', 'rapid-checkbox-label');
    checkboxEnter.append('input').attr('type', 'checkbox').attr('class', 'rapid-feature-checkbox').on('click', toggleFeature);
    checkboxEnter.append('div').attr('class', 'rapid-checkbox-custom'); // update

    rows = rows.merge(rowsEnter);
    rows.selectAll('.rapid-feature-checkbox').property('checked', isEnabled);
  }
}